window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["model-merging"]={"title":"模型合并：在共享坐标系里组合权重增量","subtitle":"从检查点平均、模型汤和任务向量，到置换对齐、符号冲突、TIES/DARE、系数搜索与安全回归。","thesis":"模型合并通过权重运算组合多个检查点，无需再次联合训练；但坐标相加只有在架构、tokenizer、参数语义和基座对齐时才可能有意义。核心风险是<b>置换不对齐、增量符号冲突与非线性能力干扰</b>，成功是经验结果而非线性代数保证。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"退款任务 ΔR=[.6,−.4,.1]","rule":"直接相加","steps":"[+.1, −.1, +.3]","interpretation":"坐标抵消并不表示任务冲突已“解决”"}}],"formulas":[{"id":"model-merging-weighted-average","section":2,"formulaIndex":1,"symbols":[{"name":"θ","meaning":"某个源检查点或合并后模型的完整参数","evidence":"θᵢ 是第 i 个源检查点的完整参数"},{"name":"i","meaning":"参与合并的源检查点编号","evidence":"第 i 个源检查点"},{"name":"α","meaning":"为每个源检查点指定的合并权重","evidence":"αᵢ 是它的合并权重"}]},{"id":"model-merging-task-vectors","section":3,"formulaIndex":1,"symbols":[{"name":"θ","meaning":"共同基座、任务模型或合并模型的完整参数","evidence":"θ基座 是所有任务微调共同出发的精确检查点"},{"name":"Δ","meaning":"任务模型相对共同基座的逐坐标参数增量","evidence":"得到任务增量 Δᵢ"},{"name":"i","meaning":"当前任务模型或任务增量的编号","evidence":"第 i 个任务模型"},{"name":"α","meaning":"控制某个任务增量加入合并模型强度的系数","evidence":"αᵢ 控制第 i 个增量加入多强"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"模型合并直接对多个模型检查点参数做运算，产生未经联合再训练的新模型。","evidence":"直接对两个或多个模型检查点的参数做运算"},"problem":{"answer":"它尝试低成本整合多个训练解，但必须先保证参数坐标具有可比较语义。","evidence":"为什么中间模型不一定能工作"},"inputOutput":{"answer":"输入是源模型权重与合并配方，输出是必须重新评测的新检查点。","evidence":"输出是必须重新评测的新模型"},"mechanism":{"answer":"兼容检查点按坐标加权；同初始化附近和低损失连通使平均更可能可用。","evidence":"存在一条路径，沿途模型损失都不高"},"interpretation":{"answer":"数组形状一致只证明数字能相加，不证明同一位置承担相同功能。","evidence":"形状相同只表示数组能相加"},"boundary":{"answer":"架构、词表、基座或表示排列不对齐时，平均可抵消有用功能并彻底失效。","evidence":"否则数字能相加但语义不能"}},{"section":2,"definition":{"answer":"检查点平均按系数对兼容源模型的每个参数坐标加权求和。","evidence":"怎样做最简单组合"},"problem":{"answer":"它平滑同一训练轨迹或同基座同任务不同超参数解的噪声与波动。","evidence":"同一次训练后期多个检查点做简单平均"},"inputOutput":{"answer":"输入是兼容检查点、权重和验证集，输出是加权检查点及泛化评测。","evidence":"输出是加权检查点及其泛化评测"},"mechanism":{"answer":"所有源参数乘 alpha 后逐坐标求和，权重和为一时形成加权平均。","evidence":"所有权重和为 1 时得到加权平均"},"interpretation":{"answer":"uniform 等权，greedy 只加入验证集有益候选，二者代表不同选择偏差。","evidence":"greedy soup 只逐个加入能改善验证集的候选"},"boundary":{"answer":"算术平均不保证坐标对齐或损失低，反复看验证集还会过拟合该验证集。","evidence":"不保证平均后损失低"}},{"section":3,"definition":{"answer":"任务向量是任务微调模型减去精确共同基座得到的参数增量。","evidence":"任务增量 Δᵢ"},"problem":{"answer":"它消除重复的共同基座，让合并聚焦每次微调究竟改变了哪些坐标。","evidence":"为什么先减同一基座比直接平均两个微调模型更可解释"},"inputOutput":{"answer":"输入是共同基座、任务模型和系数，输出是加权任务增量加回基座的新模型。","evidence":"最后再把加权增量加回共同基座"},"mechanism":{"answer":"逐坐标计算每个 Δ，按 alpha 缩放求和，再加回同一基座。","evidence":"使比较聚焦“微调改变了什么”"},"interpretation":{"answer":"反向更新会抵消，同向大更新会过冲，系数必须在独立验证集搜索。","evidence":"若都很大且同向，叠加可能过冲"},"boundary":{"answer":"任务向量不是独立语义模块，基座 revision、量化或词表不同也会失去共同原点。","evidence":"没有统一原点"}},{"section":4,"definition":{"answer":"三维例用两个任务增量的逐坐标相加展示符号抵消和同向过冲。","evidence":"两个三维任务向量怎样冲突"},"problem":{"answer":"它直观说明坐标相加后的折中不一定同时保留两个任务能力。","evidence":"直接相加留下什么"},"inputOutput":{"answer":"输入是退款与安全的三维增量，输出是和向量及每维冲突诊断。","evidence":"退款任务 ΔR=[.6,−.4,.1]"},"mechanism":{"answer":"同维数值直接相加，前两维符号相反而近乎抵消，第三维同向增强。","evidence":"维 1/2 符号冲突"},"interpretation":{"answer":"前两维接近零可能删除两种有用更新，而不是自动解决任务冲突。","evidence":"两种有用更新都被删除"},"boundary":{"answer":"真实模型单坐标大小不直接等于功能重要性，玩具例只解释符号与尺度干扰。","evidence":"单坐标大小也不直接对应功能重要性"}},{"section":5,"definition":{"answer":"置换对称指神经元编号可重排且函数不变，但参数坐标随之改变。","evidence":"神经元编号变了，组合功能没变"},"problem":{"answer":"它解释独立训练模型功能相同却无法直接按同一坐标平均的原因。","evidence":"权重坐标发生什么"},"inputOutput":{"answer":"输入是源权重或校准激活，输出是神经元、通道或注意力头对应关系。","evidence":"输出是神经元、通道或注意力头的对应关系"},"mechanism":{"answer":"权重匹配或激活匹配寻找配对，再按配对重排参数坐标。","evidence":"再按配对重排坐标"},"interpretation":{"answer":"高余弦相似只说明整体夹角接近，不能排除少数关键层不对齐。","evidence":"可掩盖少数关键层不对齐"},"boundary":{"answer":"局部置换对齐仍不保证两模型间参数路径位于同一低损失区域。","evidence":"不保证两模型之间的参数路径保持低损失"}},{"section":6,"definition":{"answer":"TIES 和 DARE 是剪小更新、处理符号或随机稀疏任务增量的经验启发式。","evidence":"处理的是经验冲突"},"problem":{"answer":"它们尝试减轻任务向量更新密集且同一坐标符号冲突造成的干扰。","evidence":"更新密集且符号冲突时"},"inputOutput":{"answer":"输入是多个任务增量和阈值、密度、随机种子，输出是稀疏或冲突处理后的增量。","evidence":"阈值、密度、随机种子和系数"},"mechanism":{"answer":"TIES 剪小值并选主符号，DARE 随机丢弃元素后重标度。","evidence":"随机丢弃任务向量元素并重标度"},"interpretation":{"answer":"减少冲突后指标改善只支持当前配方有效，不构成解析成功保证。","evidence":"这些都不是解析保证"},"boundary":{"answer":"小更新可能合成重要功能，反向更新也可能必要，随机丢弃还引入方差。","evidence":"许多小值合成重要功能"}},{"section":7,"definition":{"answer":"适配器组合在共同基座上合成多个低秩 ΔW，与完整模型权重合并不同。","evidence":"多个 LoRA 线性相加"},"problem":{"answer":"它判断多适配器同时改权重是否真正成为可用多任务模型。","evidence":"是否天然等于多任务模型"},"inputOutput":{"answer":"输入是精确基座、适配器和缩放配置，输出是分离路由或合并后的权重。","evidence":"共享精确基座时可组合"},"mechanism":{"answer":"可按系数相加各低秩增量，也可先展开后作为任务向量处理。","evidence":"先合并每个适配器再处理任务向量"},"interpretation":{"answer":"分离路由易切换回滚，合并减少推理分支却把任务干扰固定进权重。","evidence":"合并减少推理分支但固定干扰"},"boundary":{"answer":"不同 rank、scale 与目标层不可直接比大小，量化整数也需先恢复浮点语义。","evidence":"对打包整数坐标直接平均通常没有正确浮点语义"}},{"section":8,"definition":{"answer":"兼容性清单是合并前必须满足的架构、词表、基座、精度和许可条件。","evidence":"兼容性清单是硬门槛"},"problem":{"answer":"它在不兼容元数据出现时阻止无意义或不可分发的合并尝试。","evidence":"应该直接停止"},"inputOutput":{"answer":"输入是源模型元数据与许可，输出是停止决定或完整可追踪合并配方。","evidence":"保存源模型哈希、基座、系数"},"mechanism":{"answer":"逐项比对架构、tokenizer、位置、基座 revision、量化恢复和许可。","evidence":"tokenizer、词表大小/顺序、特殊 token 一致"},"interpretation":{"answer":"形状或词表大小相同仍可能 id 错序，造成嵌入和输出头语义破坏。","evidence":"token id 语义不同会直接破坏嵌入与输出头"},"boundary":{"answer":"合并产物是新的模型发布，不能沿用任一源模型名称和安全声明。","evidence":"不应沿用任一源模型名称/安全声明"}},{"section":9,"definition":{"answer":"合并评测同时覆盖源任务、交叉组合、硬风险、通用能力与系统成本。","evidence":"寻找能力干扰而不只看各自基准"},"problem":{"answer":"它发现两个单项基准维持时仍可能在组合提示中出现的能力交互失败。","evidence":"为什么组合提示仍可能失败"},"inputOutput":{"answer":"输入是源模型、候选与独立测试，输出逐样本迁移、风险、成本和回滚配方。","evidence":"输出不仅有每项分数"},"mechanism":{"answer":"比较多种合并和路由基线、画帕累托前沿、查插值损失并做模块消融。","evidence":"按系数画帕累托前沿"},"interpretation":{"answer":"插值中点损失峰值高表示直接平均跨过坏区域，合并风险更高。","evidence":"直接平均风险大"},"boundary":{"answer":"平均分不能掩盖高风险样本变不安全；成功必须可复现、可回滚且硬风险不退化。","evidence":"不能用两个平均分掩盖"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分权重平均与任务向量；解释置换和盆地兼容性；手算冲突增量；设计配方搜索与回归评测。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>权重平均为何偶尔有效、偶尔彻底崩坏<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">两个都能工作的模型取均值，为什么中间模型不一定能工作？</p><p><b>模型合并</b>直接对两个或多个模型检查点的参数做运算，产生一个新检查点，而不再用联合数据训练。输入是源模型权重与合并配方，输出是必须重新评测的新模型。</p><p>神经网络函数对参数是非线性的：参数各减半不等于功能各保留一半。“低损失连通区域”可直观理解为两个参数点之间存在一条路径，沿途模型损失都不高；若源检查点来自同一初始化附近，平均可能位于这类区域并平滑噪声。独立训练则可能让隐藏单元排列和表示基底不同，同一坐标不代表同一特征，平均会把功能抵消。</p><p>因此先确认共同基座、架构、词表、tokenizer、位置编码、归一化和参数命名。形状相同只表示数组能相加，不表示数组中同一位置承担相同功能。</p><div class=\"dd-note\"><b>合并前提：</b>先证明参数在可比较坐标系，再讨论加权公式；否则数字能相加但语义不能。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>检查点平均与模型汤<span class=\"dd-badge math\">方法</span></h2><p class=\"dd-lead\">同一训练轨迹或同一基座微调，怎样做最简单组合？</p><div class=\"dd-formula\" data-formula-id=\"model-merging-weighted-average\" data-display=\"mathml\"><math display=\"block\" aria-label=\"合并参数 theta merge 等于所有源模型参数 theta i 按系数 alpha i 加权求和，且全部系数之和等于一\"><mrow><msub><mi>θ</mi><mtext>合并</mtext></msub><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>θ</mi><mi>i</mi></msub><mo>,</mo><mspace width=\"0.8em\"/><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>α</mi><mi>i</mi></msub><mo>=</mo><mn>1</mn></mrow></math></div><p class=\"dd-formula-note\"><code>θᵢ</code> 是第 i 个源检查点的完整参数，<code>αᵢ</code> 是它的合并权重，所有权重和为 1 时得到加权平均，<code>θ合并</code> 是新模型参数。公式只保证每个坐标完成算术平均，不保证源坐标功能对齐，也不保证平均后损失低。</p><p>SWA 是对同一次训练后期多个检查点做简单平均；EMA 是让近期检查点拥有更高指数衰减权重。模型汤则平均从同一预训练初始化出发、以不同超参数微调得到的多个模型。uniform soup 全部等权，greedy soup 只逐个加入能改善验证集的候选。</p><p>输入是兼容检查点、系数和验证集，输出是加权检查点及其泛化评测。它们主要整合相近任务或数据的解，不是任意能力拼装；greedy 选择过多查看同一验证集还会造成验证集过拟合。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方法</th><th>源模型关系</th><th>目标</th><th>主要风险</th></tr></thead><tbody><tr><td>轨迹平均</td><td>同一次训练不同步</td><td>平滑解</td><td>跨越坏区域</td></tr><tr><td>模型汤</td><td>同基座同任务超参</td><td>泛化/鲁棒</td><td>验证集过拟合</td></tr><tr><td>线性插值</td><td>两个兼容检查点</td><td>折中能力</td><td>中点损失障碍</td></tr><tr><td>任务算术</td><td>同基座不同任务</td><td>组合增量</td><td>任务冲突</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>任务向量把共同基座消掉<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">为什么先减同一基座比直接平均两个微调模型更可解释？</p><div class=\"dd-formula\" data-formula-id=\"model-merging-task-vectors\" data-display=\"mathml\"><math display=\"block\" aria-label=\"第 i 个任务向量 delta i 等于任务模型参数 theta i 减共同基座参数 theta base；合并参数等于共同基座加各任务向量按 alpha i 加权求和\"><mtable><mtr><mtd><msub><mi>Δ</mi><mi>i</mi></msub><mo>=</mo><msub><mi>θ</mi><mi>i</mi></msub><mo>−</mo><msub><mi>θ</mi><mtext>基座</mtext></msub></mtd></mtr><mtr><mtd><msub><mi>θ</mi><mtext>合并</mtext></msub><mo>=</mo><msub><mi>θ</mi><mtext>基座</mtext></msub><mo>+</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>α</mi><mi>i</mi></msub><msub><mi>Δ</mi><mi>i</mi></msub></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>θ基座</code> 是所有任务微调共同出发的精确检查点，<code>θᵢ</code> 是第 i 个任务模型，二者逐坐标相减得到任务增量 <code>Δᵢ</code>。<code>αᵢ</code> 控制第 i 个增量加入多强，最后再把加权增量加回共同基座得到 <code>θ合并</code>。</p><p>任务向量使比较聚焦“微调改变了什么”，而不是重复平均共同基座。若更新在同一坐标方向相反，会抵消；若都很大且同向，叠加可能过冲。负系数有时被用来尝试削弱某方向，但不是可验证删除某项知识的保证。</p><p>任务向量不是独立语义模块：同一参数参与多个能力，线性组合会产生交叉干扰和分布外行为。系数需在独立验证集搜索并限制范围。</p><div class=\"dd-note warn\"><b>减基座要求精确相同。</b>　不同 revision、量化、词表扩展或再训练基座产生的 Δ 没有统一原点。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：两个三维任务向量怎样冲突<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">退款任务 ΔR=[.6,−.4,.1]，安全任务 ΔS=[−.5,.3,.2]，直接相加留下什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"两个三维任务向量在前两维符号冲突并经冲突处理后合并\"><rect x=\"22\" y=\"46\" width=\"190\" height=\"158\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"117\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">任务增量</text><text x=\"117\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\">ΔR=[+.6, −.4, +.1]</text><text x=\"117\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\">ΔS=[−.5, +.3, +.2]</text><text x=\"117\" y=\"174\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">维 1/2 符号冲突</text><text x=\"247\" y=\"128\" class=\"svg-t\">→</text><rect x=\"280\" y=\"46\" width=\"180\" height=\"158\" rx=\"9\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"370\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">直接相加</text><text x=\"370\" y=\"108\" text-anchor=\"middle\" class=\"svg-t\">[+.1, −.1, +.3]</text><text x=\"370\" y=\"139\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">前两维几乎抵消</text><text x=\"370\" y=\"171\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">两项能力可能都丢</text><text x=\"495\" y=\"128\" class=\"svg-t\">→</text><rect x=\"530\" y=\"46\" width=\"150\" height=\"158\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"605\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">冲突感知</text><text x=\"605\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">剪小值/选主符号</text><text x=\"605\" y=\"133\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">或分层/路由</text><text x=\"605\" y=\"171\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">仍需实测，不保证保留</text></svg><figcaption>图 1　坐标抵消并不表示任务冲突已“解决”；可能只是两种有用更新都被删除。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>维度</th><th>ΔR</th><th>ΔS</th><th>和</th><th>诊断</th></tr></thead><tbody><tr><td>1</td><td>+.6</td><td>−.5</td><td>+.1</td><td>强冲突</td></tr><tr><td>2</td><td>−.4</td><td>+.3</td><td>−.1</td><td>强冲突</td></tr><tr><td>3</td><td>+.1</td><td>+.2</td><td>+.3</td><td>同向增强/可能过冲</td></tr></tbody></table></div><p>真实模型有数十亿维，单坐标大小也不直接对应功能重要性；示例只解释为何符号与尺度干扰需要处理。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>置换对称让独立模型坐标不对齐<span class=\"dd-badge eng\">对齐</span></h2><p class=\"dd-lead\">两个两层网络交换隐藏神经元顺序，函数不变，权重坐标发生什么？</p><p>若同时交换前一层输出行和后一层输入列，网络函数可完全相同，但参数向量不同。这叫置换对称：神经元编号变了，组合功能没变。独立训练会选不同排列或表示基底，直接平均就可能把一个模型的“特征 A”与另一个的“特征 B”混合。</p><p>输入是两个源模型的权重或同一校准输入下的激活，输出是神经元、通道或注意力头的对应关系。weight matching 按权重相似寻找排列，激活匹配按响应相似配对，permutation alignment 再按配对重排坐标。即便局部对齐，也不保证两模型之间的参数路径保持低损失。</p><p>余弦相似衡量两个参数向量夹角是否接近，但大量普通坐标可掩盖少数关键层不对齐。高相似只能作为筛查信号，最终仍需插值路径损失和任务评测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>TIES、DARE 等处理的是经验冲突<span class=\"dd-badge eng\">算法</span></h2><p class=\"dd-lead\">更新密集且符号冲突时，剪枝和随机丢弃为何可能帮助？</p><p>TIES 通常先剪除小幅更新，再按聚合符号解决冲突，最后只合并与主符号一致的值；DARE 随机丢弃任务向量元素并重标度，减少密集干扰。它们假设许多增量冗余或噪声。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>步骤</th><th>希望解决</th><th>可能伤害</th></tr></thead><tbody><tr><td>剪小更新</td><td>去噪/稀疏</td><td>许多小值合成重要功能</td></tr><tr><td>统一符号</td><td>防相互抵消</td><td>少数任务必要反向更新</td></tr><tr><td>随机丢弃+重标</td><td>减少干扰</td><td>方差与不可复现</td></tr><tr><td>层级系数</td><td>细调能力</td><td>搜索空间过大</td></tr></tbody></table></div><p>这些都不是解析保证。阈值、密度、随机种子和系数必须进入配方与验证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>LoRA/适配器组合与全权重合并不同<span class=\"dd-badge eng\">适配器</span></h2><p class=\"dd-lead\">多个 LoRA 线性相加是否天然等于多任务模型？</p><p>共享精确基座时可组合 ΔWᵢ=(αᵢ/rᵢ)BᵢAᵢ，或先合并每个适配器再处理任务向量。不同 rank/scale 和目标模块导致大小不可直接比较；适配器也会在同一层冲突。</p><p>保持分离并路由，可按请求选择能力且易回滚；合并减少推理分支但固定干扰。并行激活、多适配器加权与融合均需端到端评测。不要把路由（选择一个）和合并（同时改变权重）混为一谈。</p><div class=\"dd-note warn\"><b>先解量化再运算。</b>　对打包整数坐标直接平均通常没有正确浮点语义；合并后需重新校准量化。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>兼容性清单是硬门槛<span class=\"dd-badge eng\">工程</span></h2><p class=\"dd-lead\">哪些元数据不一致时应该直接停止，而不是“先试试”？</p><ol class=\"dd-steps\"><li>架构、层数、隐藏维度和参数命名一致。</li><li>tokenizer、词表大小/顺序、特殊 token 一致。</li><li>位置编码、归一化、chat template 一致。</li><li>精确共同基座与 revision 可验证。</li><li>权重 dtype/量化恢复方式明确。</li><li>许可允许产生与分发合并产物。</li></ol><p>保存源模型哈希、基座、系数、层级规则、剪枝阈值、随机种子、代码版本和结果哈希。合并是新的模型发布，不应沿用任一源模型名称/安全声明。</p><div class=\"dd-note warn\"><b>词表同大小仍可能错序。</b>　token id 语义不同会直接破坏嵌入与输出头。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要寻找能力干扰而不只看各自基准<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">退款与安全基准都维持，为什么组合提示仍可能失败？</p><p>输入是源模型、合并候选和独立的单任务、交叉组合、冲突指令、通用、长上下文、工具与安全测试。输出不仅有每项分数，还应保存逐样本能力迁移、硬风险结果、系统成本和可回滚配方。</p><p>比较源模型、简单平均、任务向量、冲突方法、联合微调和路由基线；按系数画帕累托前沿，即无法在不牺牲另一项指标时继续改善某项的候选边界。单任务分数都维持而组合提示失败，表示能力交互没有被单项评测覆盖。</p><p>检查插值路径损失：若从 θA 到 θB 的中间模型出现高损失峰值，直接平均风险大。逐层或模块消融可定位干扰。不能用两个平均分掩盖同一高风险样本从安全变不安全。</p><div class=\"dd-note\"><b>成功定义：</b>合并产物在目标组合上提供真实质量/成本收益，硬风险不退化，并有可复现配方与回滚。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">模型合并是坐标兼容性和经验评测问题，不是“文件相加就继承能力”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>两个好模型平均仍好</td><td>需参数对齐和低损失连通</td></tr><tr><td>形状相同就兼容</td><td>词表、语义坐标和基座也需一致</td></tr><tr><td>冲突抵消是自动折中</td><td>可能让两项能力同时丢失</td></tr><tr><td>TIES/DARE 保证组合成功</td><td>是经验启发式，需超参搜索和评测</td></tr><tr><td>合并源模型安全声明可继承</td><td>合并产物是新模型，行为需重新验证</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>参数空间、微调、线性代数和神经元置换</td></tr><tr><td><b>本页核心</b></td><td>权重平均、任务向量、对齐、符号冲突、系数搜索</td></tr><tr><td>组合</td><td>LoRA/适配器、量化、模型路由</td></tr><tr><td>验证</td><td>模型评测、数据治理、部署与安全回归</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>验证共同基座与参数语义</li><li>计算权重/任务增量</li><li>诊断置换、尺度与符号冲突</li><li>搜索合并方法和系数</li><li>源任务/交叉/基础/安全联合回归</li><li>保存配方与新模型发布/回滚</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么独立训练模型难直接平均？</li><li>任务向量是什么？</li><li>示例直接相加结果是什么？</li><li>TIES/DARE 是否提供保证？</li><li>合并后为何要重新安全评测？</li><li>假设“模型合并：在共享坐标系里组合权重增量”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“模型合并：在共享坐标系里组合权重增量”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>隐藏单元排列、表示基底和参数盆地可能不对齐。</li><li>某任务微调权重减去精确共同基座。</li><li>[.1,−.1,.3]，前两维因反向更新几乎抵消。</li><li>不提供，是处理密集/冲突增量的经验方法。</li><li>非线性交互可改变拒答和组合行为，源声明不能继承。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2203.05482\" target=\"_blank\" rel=\"noopener\">Model soups</a>：同初始化模型权重平均</li><li><a href=\"https://arxiv.org/abs/2212.04089\" target=\"_blank\" rel=\"noopener\">Editing Models with Task Arithmetic</a>：任务向量与参数算术</li><li><a href=\"https://arxiv.org/abs/2306.01708\" target=\"_blank\" rel=\"noopener\">TIES-Merging</a>：剪枝、符号选举与冲突合并</li><li><a href=\"https://arxiv.org/abs/2209.04836\" target=\"_blank\" rel=\"noopener\">Git Re-Basin</a>：置换对齐与低损失连接</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
